   218  static int set_data(
   219          git_pkt_parse_data *data,
   220          const char *line,
   221          size_t len)
   222  {
   223          const char *caps, *format_str = NULL, *eos;
   224          size_t format_len;
   225          git_oid_t remote_oid_type;
   226
   227          GIT_ASSERT_ARG(data);
   228
   229          if ((caps = memchr(line, '\0', len)) != NULL) {
   230                  caps++;
   231
   232                  if (strncmp(caps, "object-format=", CONST_STRLEN("object-format=")) == 0)
   233                          format_str = caps + CONST_STRLEN("object-format=");
   234                  else if ((format_str = strstr(caps, " object-format=")) != NULL)
   235                          format_str += CONST_STRLEN(" object-format=");
   236          }
   237
   238          if (format_str) {
   239                  if ((eos = strchr(format_str, ' ')) == NULL)
   240                          eos = strchr(format_str, '\0');
   241
   242                  GIT_ASSERT(eos);
   243
   244                  format_len = eos - format_str;
   245
   246                  if ((remote_oid_type = git_oid_type_fromstrn(format_str, format_len)) == 0) {
   247                          git_error_set(GIT_ERROR_INVALID, "unknown remote object format '%.*s'", (int)format_len, format_str);
   248                          return -1;
   249                  }
   250          } else {
   251                  remote_oid_type = GIT_OID_SHA1;
   252          }
   253
   254          if (!data->oid_type) {
   255                  data->oid_type = remote_oid_type;
   256          } else if (data->oid_type != remote_oid_type) {
   257                  git_error_set(GIT_ERROR_INVALID,
   258                                "the local object format '%s' does not match the remote object format '%s'",
   259                                git_oid_type_name(data->oid_type),
   260                                git_oid_type_name(remote_oid_type));
   261                  return -1;
   262          }
   263
   264          return 0;
   265  }
