   267  /*
   268   * Parse an other-ref line.
   269   */
   270  static int ref_pkt(
   271          git_pkt **out,
   272          const char *line,
   273          size_t len,
   274          git_pkt_parse_data *data)
   275  {
   276          git_pkt_ref *pkt;
   277          size_t alloclen, oid_hexsize;
   278
   279          pkt = git__calloc(1, sizeof(git_pkt_ref));
   280          GIT_ERROR_CHECK_ALLOC(pkt);
   281          pkt->type = GIT_PKT_REF;
   282
   283          /* Determine OID type from capabilities */
   284          if (!data->seen_capabilities && set_data(data, line, len) < 0)
   285                  return -1;
   286
   287          GIT_ASSERT(data->oid_type);
   288          oid_hexsize = git_oid_hexsize(data->oid_type);
   289
   290          if (len < oid_hexsize ||
   291              git_oid__fromstr(&pkt->head.oid, line, data->oid_type) < 0)
   292                  goto out_err;
   293          line += oid_hexsize;
   294          len -= oid_hexsize;
   295
   296          if (git__prefixncmp(line, len, " "))
   297                  goto out_err;
   298
   299          line++;
   300          len--;
   301
   302          if (!len)
   303                  goto out_err;
   304
   305          if (line[len - 1] == '\n')
   306                  --len;
   307
   308          GIT_ERROR_CHECK_ALLOC_ADD(&alloclen, len, 1);
   309          pkt->head.name = git__malloc(alloclen);
   310          GIT_ERROR_CHECK_ALLOC(pkt->head.name);
   311
   312          memcpy(pkt->head.name, line, len);
   313          pkt->head.name[len] = '\0';
   314
   315          if (strlen(pkt->head.name) < len) {
   316                  if (!data->seen_capabilities)
   317                          pkt->capabilities = strchr(pkt->head.name, '\0') + 1;
   318                  else
   319                          goto out_err;
   320          }
   321
   322          data->seen_capabilities = 1;
   323
   324          *out = (git_pkt *)pkt;
   325          return 0;
   326
   327  out_err:
   328          git_error_set(GIT_ERROR_NET, "error parsing REF pkt-line");
   329          if (pkt)
   330                  git__free(pkt->head.name);
   331          git__free(pkt);
   332          return -1;
   333  }
