   335  static int ok_pkt(git_pkt **out, const char *line, size_t len)
   336  {
   337          git_pkt_ok *pkt;
   338          size_t alloc_len;
   339
   340          pkt = git__malloc(sizeof(*pkt));
   341          GIT_ERROR_CHECK_ALLOC(pkt);
   342          pkt->type = GIT_PKT_OK;
   343
   344          if (git__prefixncmp(line, len, "ok "))
   345                  goto out_err;
   346          line += 3;
   347          len -= 3;
   348
   349          if (len && line[len - 1] == '\n')
   350                  --len;
   351
   352          GIT_ERROR_CHECK_ALLOC_ADD(&alloc_len, len, 1);
   353          pkt->ref = git__malloc(alloc_len);
   354          GIT_ERROR_CHECK_ALLOC(pkt->ref);
   355
   356          memcpy(pkt->ref, line, len);
   357          pkt->ref[len] = '\0';
   358
   359          *out = (git_pkt *)pkt;
   360          return 0;
   361
   362  out_err:
   363          git_error_set(GIT_ERROR_NET, "error parsing OK pkt-line");
   364          git__free(pkt);
   365          return -1;
   366  }
