   368  static int ng_pkt(git_pkt **out, const char *line, size_t len)
   369  {
   370          git_pkt_ng *pkt;
   371          const char *ptr, *eol;
   372          size_t alloclen;
   373
   374          pkt = git__malloc(sizeof(*pkt));
   375          GIT_ERROR_CHECK_ALLOC(pkt);
   376
   377          pkt->ref = NULL;
   378          pkt->type = GIT_PKT_NG;
   379
   380          eol = line + len;
   381
   382          if (git__prefixncmp(line, len, "ng "))
   383                  goto out_err;
   384          line += 3;
   385
   386          if (!(ptr = memchr(line, ' ', eol - line)))
   387                  goto out_err;
   388          len = ptr - line;
   389
   390          GIT_ERROR_CHECK_ALLOC_ADD(&alloclen, len, 1);
   391          pkt->ref = git__malloc(alloclen);
   392          GIT_ERROR_CHECK_ALLOC(pkt->ref);
   393
   394          memcpy(pkt->ref, line, len);
   395          pkt->ref[len] = '\0';
   396
   397          line = ptr + 1;
   398          if (line >= eol)
   399                  goto out_err;
   400
   401          if (!(ptr = memchr(line, '\n', eol - line)))
   402                  goto out_err;
   403          len = ptr - line;
   404
   405          GIT_ERROR_CHECK_ALLOC_ADD(&alloclen, len, 1);
   406          pkt->msg = git__malloc(alloclen);
   407          GIT_ERROR_CHECK_ALLOC(pkt->msg);
   408
   409          memcpy(pkt->msg, line, len);
   410          pkt->msg[len] = '\0';
   411
   412          *out = (git_pkt *)pkt;
   413          return 0;
   414
   415  out_err:
   416          git_error_set(GIT_ERROR_NET, "invalid packet line");
   417          git__free(pkt->ref);
   418          git__free(pkt);
   419          return -1;
   420  }
