   439  static int parse_len(size_t *out, const char *line, size_t linelen)
   440  {
   441          char num[PKT_LEN_SIZE + 1];
   442          int i, k, error;
   443          int32_t len;
   444          const char *num_end;
   445
   446          /* Not even enough for the length */
   447          if (linelen < PKT_LEN_SIZE)
   448                  return GIT_EBUFS;
   449
   450          memcpy(num, line, PKT_LEN_SIZE);
   451          num[PKT_LEN_SIZE] = '\0';
   452
   453          for (i = 0; i < PKT_LEN_SIZE; ++i) {
   454                  if (!isxdigit(num[i])) {
   455                          /* Make sure there are no special characters before passing to error message */
   456                          for (k = 0; k < PKT_LEN_SIZE; ++k) {
   457                                  if(!isprint(num[k])) {
   458                                          num[k] = '.';
   459                                  }
   460                          }
   461
   462                          git_error_set(GIT_ERROR_NET, "invalid hex digit in length: '%s'", num);
   463                          return -1;
   464                  }
   465          }
   466
   467          if ((error = git__strntol32(&len, num, PKT_LEN_SIZE, &num_end, 16)) < 0)
   468                  return error;
   469
   470          if (len < 0)
   471                  return -1;
   472
   473          *out = (size_t) len;
   474          return 0;
   475  }
