   477  /*
   478   * As per the documentation, the syntax is:
   479   *
   480   * pkt-line     = data-pkt / flush-pkt
   481   * data-pkt     = pkt-len pkt-payload
   482   * pkt-len              = 4*(HEXDIG)
   483   * pkt-payload = (pkt-len -4)*(OCTET)
   484   * flush-pkt    = "0000"
   485   *
   486   * Which means that the first four bytes are the length of the line,
   487   * in ASCII hexadecimal (including itself)
   488   */
   489
   490  int git_pkt_parse_line(
   491          git_pkt **pkt,
   492          const char **endptr,
   493          const char *line,
   494          size_t linelen,
   495          git_pkt_parse_data *data)
   496  {
   497          int error;
   498          size_t len;
   499
   500          if ((error = parse_len(&len, line, linelen)) < 0) {
   501                  /*
   502                   * If we fail to parse the length, it might be
   503                   * because the server is trying to send us the
   504                   * packfile already or because we do not yet have
   505                   * enough data.
   506                   */
   507                  if (error == GIT_EBUFS)
   508                          ;
   509                  else if (!git__prefixncmp(line, linelen, "PACK"))
   510                          git_error_set(GIT_ERROR_NET, "unexpected pack file");
   511                  else
   512                          git_error_set(GIT_ERROR_NET, "bad packet length");
   513                  return error;
   514          }
   515
   516          /*
   517           * Make sure there is enough in the buffer to satisfy
   518           * this line.
   519           */
   520          if (linelen < len)
   521                  return GIT_EBUFS;
   522
   523          /*
   524           * The length has to be exactly 0 in case of a flush
   525           * packet or greater than PKT_LEN_SIZE, as the decoded
   526           * length includes its own encoded length of four bytes.
   527           */
   528          if (len != 0 && len < PKT_LEN_SIZE)
   529                  return GIT_ERROR;
   530
   531          line += PKT_LEN_SIZE;
   532          /*
   533           * The Git protocol does not specify empty lines as part
   534           * of the protocol. Not knowing what to do with an empty
   535           * line, we should return an error upon hitting one.
   536           */
   537          if (len == PKT_LEN_SIZE) {
   538                  git_error_set_str(GIT_ERROR_NET, "Invalid empty packet");
   539                  return GIT_ERROR;
   540          }
   541
   542          if (len == 0) { /* Flush pkt */
   543                  *endptr = line;
   544                  return flush_pkt(pkt);
   545          }
   546
   547          len -= PKT_LEN_SIZE; /* the encoded length includes its own size */
   548
   549          if (*line == GIT_SIDE_BAND_DATA)
   550                  error = data_pkt(pkt, line, len);
   551          else if (*line == GIT_SIDE_BAND_PROGRESS)
   552                  error = sideband_progress_pkt(pkt, line, len);
   553          else if (*line == GIT_SIDE_BAND_ERROR)
   554                  error = sideband_error_pkt(pkt, line, len);
   555          else if (!git__prefixncmp(line, len, "ACK"))
   556                  error = ack_pkt(pkt, line, len);
   557          else if (!git__prefixncmp(line, len, "NAK"))
   558                  error = nak_pkt(pkt);
   559          else if (!git__prefixncmp(line, len, "ERR"))
   560                  error = err_pkt(pkt, line, len);
   561          else if (*line == '#')
   562                  error = comment_pkt(pkt, line, len);
   563          else if (!git__prefixncmp(line, len, "ok"))
   564                  error = ok_pkt(pkt, line, len);
   565          else if (!git__prefixncmp(line, len, "ng"))
   566                  error = ng_pkt(pkt, line, len);
   567          else if (!git__prefixncmp(line, len, "unpack"))
   568                  error = unpack_pkt(pkt, line, len);
   569          else
   570                  error = ref_pkt(pkt, line, len, data);
   571
   572          *endptr = line + len;
   573
   574          return error;
   575  }
