   577  void git_pkt_free(git_pkt *pkt)
   578  {
   579          if (pkt == NULL) {
   580                  return;
   581          }
   582          if (pkt->type == GIT_PKT_REF) {
   583                  git_pkt_ref *p = (git_pkt_ref *) pkt;
   584                  git__free(p->head.name);
   585                  git__free(p->head.symref_target);
   586          }
   587
   588          if (pkt->type == GIT_PKT_OK) {
   589                  git_pkt_ok *p = (git_pkt_ok *) pkt;
   590                  git__free(p->ref);
   591          }
   592
   593          if (pkt->type == GIT_PKT_NG) {
   594                  git_pkt_ng *p = (git_pkt_ng *) pkt;
   595                  git__free(p->ref);
   596                  git__free(p->msg);
   597          }
   598
   599          git__free(pkt);
   600  }
